-- 234: Trainer Application landing page. Renders on the existing Trainer
--      Application menu/footer URL (category 114 -> /trainer-application.html) via a
--      static block holding the pitch + embedded form (mmd_trainer/form.phtml,
--      honeypot + invisible Cloudflare Turnstile, posts to trainer/index/post).
--      Content hex-encoded (page CSS would trip the apply.php splitter).

INSERT INTO cms_block (title, identifier, content, creation_time, update_time, is_active)
SELECT 'Trainer Landing', 'trainer_landing', , NOW(), NOW(), 1 FROM dual
WHERE NOT EXISTS (SELECT 1 FROM (SELECT block_id FROM cms_block WHERE identifier='trainer_landing') t);

INSERT INTO cms_block_store (block_id, store_id) SELECT b.block_id, 0 FROM cms_block b WHERE b.identifier='trainer_landing' AND NOT EXISTS (SELECT 1 FROM cms_block_store s WHERE s.block_id=b.block_id);

INSERT INTO catalog_category_entity_varchar (entity_type_id, attribute_id, store_id, entity_id, value) VALUES (3,49,0,114,'PAGE') ON DUPLICATE KEY UPDATE value='PAGE';

INSERT INTO catalog_category_entity_int (entity_type_id, attribute_id, store_id, entity_id, value) SELECT 3,50,0,114,b.block_id FROM cms_block b WHERE b.identifier='trainer_landing' LIMIT 1 ON DUPLICATE KEY UPDATE value=VALUES(value);
